args.CodeContent:
import { NavLink } from 'react-router-dom'
import { useRole, ROLES } from '../store/useRole'
import {
  LayoutDashboard, FolderKanban, CheckSquare, Users,
  Wallet, BarChart2, Bell,
  ChevronLeft, ChevronRight, Boxes,
} from 'lucide-react'

// Nav items — roles array controls visibility exactly per Dashboard.png spec
const ALL_NAV = [
  // ── Dashboard (all roles) ────────────────────────────────────
  {
    to: '/dashboard',
    icon: LayoutDashboard,
    label: 'Dashboard',
    roles: [ROLES.ADMIN, ROLES.PM, ROLES.EMPLOYEE],
  },
  // ── Projects: Admin + PM see "Projects"; Employee sees "My Projects" ──
  {
    to: '/projects',
    icon: FolderKanban,
    label: 'Projects',
    roles: [ROLES.ADMIN, ROLES.PM],
  },
  {
    to: '/projects',
    icon: FolderKanban,
    label: 'My Projects',
    roles: [ROLES.EMPLOYEE],
  },
  // ── Tasks: PM sees "Tasks"; Employee sees "My Tasks" ─────────
  {
    to: '/tasks',
    icon: CheckSquare,
    label: 'Tasks',
    roles: [ROLES.PM],
  },
  {
    to: '/tasks',
    icon: CheckSquare,
    label: 'My Tasks',
    roles: [ROLES.EMPLOYEE],
  },
  // ── Users: Admin sees "Users"; PM sees "Team Members" ────────
  {
    to: '/users',
    icon: Users,
    label: 'Users',
    roles: [ROLES.ADMIN],
  },
  {
    to: '/users',
    icon: Users,
    label: 'Team Members',
    roles: [ROLES.PM],
  },
  // ── Resources: Admin + PM only ───────────────────────────────
  {
    to: '/resources',
    icon: Boxes,
    label: 'Resources',
    roles: [ROLES.ADMIN, ROLES.PM],
  },
  // ── Budgets: Admin + PM only ─────────────────────────────────
  {
    to: '/budgets',
    icon: Wallet,
    label: 'Budgets',
    roles: [ROLES.ADMIN, ROLES.PM],
  },
  // ── Reports: Admin + PM only ─────────────────────────────────
  {
    to: '/reports',
    icon: BarChart2,
    label: 'Reports',
    roles: [ROLES.ADMIN, ROLES.PM],
  },
  // ── Notifications: all roles ─────────────────────────────────
  {
    to: '/notifications',
    icon: Bell,
    label: 'Notifications',
    roles: [ROLES.ADMIN, ROLES.PM, ROLES.EMPLOYEE],
  },
]

export default function Sidebar({ collapsed, onToggle, notifCount = 0 }) {
  const { role } = useRole()

  // Filter nav items by role
  const navItems = ALL_NAV.filter(item => item.roles.includes(role))

  return (
    <aside
      className="sidebar"
      style={{ width: collapsed ? 'var(--sidebar-collapsed)' : 'var(--sidebar-width)' }}
    >
      {/* ── Logo ─────────────────────────────────────────────── */}
      <div className="sidebar-logo">
        <div className="sidebar-logo-icon">
          <img src="/logo.svg" alt="Planora" width={20} height={20}
            onError={e => { e.target.style.display = 'none' }}
          />
          <span style={{ display: 'none' }}>P</span>
        </div>
        {!collapsed && (
          <div>
            <div className="sidebar-brand">Planora</div>
            <div className="sidebar-brand-sub">Project Management System</div>
          </div>
        )}
      </div>

      {/* ── Nav ──────────────────────────────────────────────── */}
      <nav className="sidebar-nav">
        {navItems.map(({ to, icon: Icon, label }) => (
          <NavLink
            key={label}
            to={to}
            className={({ isActive }) =>
              'sidebar-link' + (isActive ? ' active' : '')
            }
            title={collapsed ? label : undefined}
          >
            <div className="sidebar-link-icon">
              <Icon size={17} strokeWidth={1.7} />
              {label === 'Notifications' && notifCount > 0 && (
                <span className="sidebar-notif-badge">{notifCount}</span>
              )}
            </div>
            {!collapsed && <span className="sidebar-link-text">{label}</span>}
          </NavLink>
        ))}
      </nav>

      {/* ── Collapse toggle — icon only ──────────────────────── */}
      <button className="sidebar-collapse-btn" onClick={onToggle} title={collapsed ? 'Expand' : 'Collapse'}>
        {collapsed ? <ChevronRight size={15} /> : <ChevronLeft size={15} />}
      </button>
    </aside>
  )
}

