/* ── Sidebar ─────────────────────────────────────────────── */
.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  background: linear-gradient(180deg, #0f1023 0%, #131629 60%, #0d0f1e 100%);
  border-right: 1px solid rgba(99, 102, 241, 0.12);
  display: flex;
  flex-direction: column;
  z-index: 200;
  transition: width var(--ease-md);
  overflow: hidden;
  box-shadow: 4px 0 24px rgba(0, 0, 0, 0.35);
}

.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 16px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  flex-shrink: 0;
}

.sidebar-logo-icon {
  width: 34px;
  height: 34px;
  background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 0.9rem;
  font-weight: 800;
  color: #fff;
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.45);
}

.sidebar-brand {
  font-size: 0.95rem;
  font-weight: 700;
  color: #f0f0ff;
  white-space: nowrap;
  letter-spacing: 0.02em;
}

.sidebar-brand-sub {
  font-size: 0.65rem;
  color: rgba(255, 255, 255, 0.35);
  white-space: nowrap;
  margin-top: 2px;
  letter-spacing: 0.03em;
}

.sidebar-nav {
  flex: 1;
  padding: 12px 10px;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: none;
}

.sidebar-nav::-webkit-scrollbar {
  display: none;
}

.sidebar-link {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 12px;
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.48);
  font-size: 0.855rem;
  font-weight: 500;
  margin-bottom: 3px;
  transition: all 0.18s ease;
  white-space: nowrap;
  position: relative;
  letter-spacing: 0.01em;
}

.sidebar-link:hover {
  background: rgba(99, 102, 241, 0.12);
  color: rgba(255, 255, 255, 0.85);
}

.sidebar-link.active {
  background: linear-gradient(135deg, rgba(99,102,241,0.28) 0%, rgba(139,92,246,0.18) 100%);
  color: #c4b5fd;
  border: 1px solid rgba(99, 102, 241, 0.25);
  box-shadow: 0 0 14px rgba(99, 102, 241, 0.15), inset 0 1px 0 rgba(255,255,255,0.06);
}

.sidebar-link.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 22%;
  bottom: 22%;
  width: 3px;
  background: linear-gradient(180deg, #6366f1, #a78bfa);
  border-radius: 0 3px 3px 0;
  box-shadow: 0 0 8px rgba(99, 102, 241, 0.7);
}

.sidebar-link-icon {
  position: relative;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.sidebar-notif-badge {
  position: absolute;
  top: -6px;
  right: -7px;
  background: #ef4444;
  color: #fff;
  font-size: 0.58rem;
  font-weight: 700;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1.5px solid #0f1023;
}

.sidebar-link-text {
  flex: 1;
}

.sidebar-collapse-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 13px 16px;
  color: rgba(255, 255, 255, 0.3);
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  transition: color 0.18s ease, background 0.18s ease;
  flex-shrink: 0;
}

.sidebar-collapse-btn:hover {
  color: rgba(255, 255, 255, 0.75);
  background: rgba(99, 102, 241, 0.08);
}

