import { useState } from 'react'
import { ChevronLeft } from 'lucide-react'
import { projectApi } from '../../../api/projectApi'

export default function BudgetFormModal({ mode, budget, projects, onClose, onSaved }) {
  const isAdd = mode === 'add'

  const [projectId, setProjectId] = useState(budget?.id || '')
  const [budgetType, setBudgetType] = useState(budget?.budgetType || '')
  const [budgetName, setBudgetName] = useState(budget?.budgetName || '')
  const [totalBudget, setTotalBudget] = useState(budget?.totalBudget || '')
  const [description, setDescription] = useState(budget?.description || '')
  const [loading, setLoading] = useState(false)

  const handleSave = async () => {
    if (!projectId || !totalBudget) return alert('Project and Total Budget are required.')

    setLoading(true)
    try {
      // Find the existing project so we can preserve its other fields
      const proj = projects.find(p => String(p.projectId) === String(projectId))
      if (!proj) throw new Error('Project not found')

      // Update the project with the new budget amount
      await projectApi.update(projectId, { 
        ...proj,
        budget: Number(totalBudget)
      })

      onSaved()
    } catch (err) {
      console.error(err)
      alert('Failed to save budget.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }} onClick={onClose}>
      <div style={{ width: '100%', maxWidth: 600, maxHeight: '90vh', overflowY: 'auto', background: 'var(--bg-card)', borderRadius: 12 }} className="card" onClick={e => e.stopPropagation()}>
        <div style={{ padding: '24px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 24, fontWeight: 700, cursor: 'pointer', fontSize: '1.1rem' }} onClick={onClose}>
            <ChevronLeft size={18} /> {isAdd ? 'Add Budget' : 'Edit Budget'}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 20 }}>
            <div>
              <label className="form-label" style={{ fontSize: '0.85rem' }}>Project <span style={{ color: 'red' }}>*</span></label>
              <select className="form-select" value={projectId} onChange={e => setProjectId(e.target.value)} disabled={!isAdd}>
                <option value="">Select Project</option>
                {projects.map(p => <option key={p.projectId} value={p.projectId}>{p.projectName}</option>)}
              </select>
            </div>
            <div>
              <label className="form-label" style={{ fontSize: '0.85rem' }}>Budget Type <span style={{ color: 'red' }}>*</span></label>
              <select className="form-select" value={budgetType} onChange={e => setBudgetType(e.target.value)}>
                <option value="">Select Type</option>
                <option value="Fixed">Fixed</option>
                <option value="Estimated">Estimated</option>
              </select>
            </div>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 20 }}>
            <div>
              <label className="form-label" style={{ fontSize: '0.85rem' }}>Budget Name <span style={{ color: 'red' }}>*</span></label>
              <input type="text" className="form-input" placeholder="Enter budget name" value={budgetName} onChange={e => setBudgetName(e.target.value)} />
            </div>
            <div>
              <label className="form-label" style={{ fontSize: '0.85rem' }}>Total Budget (₹) <span style={{ color: 'red' }}>*</span></label>
              <input type="number" className="form-input" placeholder="Enter amount" value={totalBudget} onChange={e => setTotalBudget(e.target.value)} />
            </div>
          </div>
          <div style={{ marginBottom: 24 }}>
            <label className="form-label" style={{ fontSize: '0.85rem' }}>Description (Optional)</label>
            <textarea 
              className="form-input" 
              rows={4} 
              placeholder="Enter description..." 
              value={description}
              onChange={e => setDescription(e.target.value)}
              style={{ width: '100%', boxSizing: 'border-box', resize: 'none', overflow: 'hidden', minHeight: '100px' }}
              onInput={(e) => {
                e.target.style.height = 'auto';
                e.target.style.height = `${e.target.scrollHeight}px`;
              }}
            ></textarea>
            <div style={{ textAlign: 'right', fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 4 }}>{description.length}/200</div>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <button className="btn btn-outline" onClick={onClose} style={{ padding: '8px 24px' }} disabled={loading}>Cancel</button>
            <button className="btn btn-primary" onClick={handleSave} style={{ padding: '8px 24px' }} disabled={loading}>
              {loading ? 'Saving...' : (isAdd ? 'Save Budget' : 'Update Budget')}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

