        <div style={{ display: 'flex', gap: 12 }}>
          <button 
            className="btn btn-ghost" 
            onClick={() => { setSearch(''); setSearchInput(''); setRoleF(''); setStatusF(''); setDeptF(''); setPage(1); }} 
            style={{ height: 38, border: '1px solid var(--purple-light)', color: 'var(--purple)', display: 'flex', alignItems: 'center', gap: 8, padding: '0 16px', fontWeight: 500, fontSize: '0.85rem', cursor: 'pointer' }}
