                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Department</th>
                    <th>Status</th>
                    <th>Joined On</th>
                    <th style={{ textAlign: 'center' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paged.length === 0
                    ? <tr><td colSpan={8} className="table-empty">No users found</td></tr>
                    : paged.map(u => {
                      const name = u.fullName || `${u.firstName || ''} ${u.lastName || ''}`.trim()
                      const rBadge = getRoleBadge(u.role);
                      const sBadge = getStatusBadge(u.status);

                      return (
                        <tr key={u.userId}>
                          <td style={{ fontWeight: 600, fontSize: '0.875rem', color: 'var(--text-secondary)' }}>U-{u.userId}</td>
                          <td>
                            <div className="user-cell">
                              <div className="avatar avatar-sm">{initials(name)}</div>
                              <span style={{ fontWeight: 600, fontSize: '0.875rem' }}>{name}</span>
