            {/* Pagination */}
            <div className="pagination" style={{ borderTop: '1px solid var(--border)' }}>
              <span>Showing {total === 0 ? 0 : Math.min((page - 1) * pageSize + 1, total)} to {Math.min(page * pageSize, total)} of {total} users</span>
              <div className="pag-controls">
