import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { resourceApi } from '../../../api/resourceApi'
import { userApi }     from '../../../api/userApi'
import { projectApi }  from '../../../api/projectApi'
import { Plus, Search, Eye, Pencil, MoreVertical } from 'lucide-react'
import { initials } from '../../../utils/formatDate'
import AllocateModal from '../components/AllocationForm'

// Map common roles → skill tags
const ROLE_SKILLS = {
  'PROJECT_MANAGER': ['Management', 'Planning', 'Leadership'],
  'ADMIN':           ['Administration', 'Management', 'Config'],
  'EMPLOYEE':        ['Development', 'Teamwork'],
  'FRONTEND':        ['React', 'JavaScript', 'UI/UX'],
  'BACKEND':         ['Java', 'Spring Boot', 'API'],
  'QA':              ['Testing', 'Selenium', 'Jira'],
  'DESIGNER':        ['Figma', 'UI Design', 'UX Research'],
  'DEVOPS':          ['AWS', 'Docker', 'CI/CD'],
  'ANALYST':         ['Analysis', 'Documentation', 'SQL'],
}

function getSkillsForUser(u) {
  const byRole = ROLE_SKILLS[u.role] || ROLE_SKILLS['EMPLOYEE']
  if (u.designation) {
    const d = u.designation.toUpperCase()
    if (d.includes('FRONTEND')) return ROLE_SKILLS['FRONTEND']
    if (d.includes('BACKEND'))  return ROLE_SKILLS['BACKEND']
    if (d.includes('QA'))       return ROLE_SKILLS['QA']
    if (d.includes('DESIGN'))   return ROLE_SKILLS['DESIGNER']
    if (d.includes('DEVOPS'))   return ROLE_SKILLS['DEVOPS']
    if (d.includes('ANALYST'))  return ROLE_SKILLS['ANALYST']
  }
  return byRole
}

function getAvatarColor(name) {
  const colors = [
    { bg: '#ede9fe', color: '#7c3aed' }, // purple
    { bg: '#d1fae5', color: '#059669' }, // green
    { bg: '#ffedd5', color: '#ea580c' }, // orange
    { bg: '#dbeafe', color: '#2563eb' }, // blue
    { bg: '#fae8ff', color: '#c026d3' }, // pink
  ];
  if (!name) return colors[0];
  const charCode = name.charCodeAt(0);
  return colors[charCode % colors.length];
}

export default function ResourceAllocationPage() {
  const qc = useQueryClient()

  // ── Filters
  const [search, setSearch] = useState('')
  const [searchInput, setSearchInput] = useState('')
  const [projectF, setProjectF] = useState('')
  const [roleF,  setRoleF]  = useState('')
  const [availF, setAvailF] = useState('')

  // ── Modals / Menus
  const [showForm, setForm] = useState(false)
  const [editing, setEdit]  = useState(null)
  const [openMenuId, setOpenMenuId] = useState(null)

  useEffect(() => {
    const handleClickOutside = () => setOpenMenuId(null);
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const [page, setPage]     = useState(1)
  const pageSize = 12

  const { data: resources = [] } = useQuery({
    queryKey: ['resources-list'],
    queryFn:  () => resourceApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 30_000,
  })

  const { data: users = [], isLoading } = useQuery({
    queryKey: ['users-list'],
    queryFn:  () => userApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 60_000,
  })

  const { data: projects = [] } = useQuery({
    queryKey: ['projects-list'],
    queryFn:  () => projectApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 60_000,
  })

  // Get allocation info for a user
  function getUserAllocation(userId) {
    const r = resources.filter(x => x.userId === userId)
    if (!r.length) return { pct: 0, projectNames: '', avail: 'AVAILABLE' }
    const pct = Math.min(r.reduce((s, x) => s + (x.allocationPercentage || 0), 0), 100)
    const projectNames = r.map(x => x.projectName || '').filter(Boolean).join(', ')
    const avail = pct >= 100 ? 'UNAVAILABLE' : pct > 0 ? 'PARTIALLY_AVAILABLE' : 'AVAILABLE'
    return { pct, projectNames, avail, projectIds: r.map(x => x.projectId).filter(Boolean) }
  }

  const filtered = users.filter(u => {
    const name = u.fullName || `${u.firstName || ''} ${u.lastName || ''}`

    // Search Match
    let matchS = true
    if (search) {
      const s = search.toLowerCase()
      const skillsText = getSkillsForUser(u).join(' ').toLowerCase()
      matchS = name.toLowerCase().includes(s) || u.email?.toLowerCase().includes(s) || skillsText.includes(s)
    }

    // Role Match
    const matchR = !roleF || u.role === roleF || u.designation === roleF

    const { avail, projectIds, projectNames } = getUserAllocation(u.userId)

    // Avail Match
    const matchA = !availF || avail === availF

    // Project Match
    const matchP = !projectF || projectIds.includes(Number(projectF)) || projectNames.includes(projectF)

    return matchS && matchR && matchA && matchP
  })

  const total = filtered.length
  const pages = Math.max(1, Math.ceil(total / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)

  function availBadge(avail) {
    if (avail === 'UNAVAILABLE') return { color: '#dc2626', bg: '#fee2e2', text: 'Unavailable', dot: '#dc2626' }
    if (avail === 'PARTIALLY_AVAILABLE') return { color: '#ea580c', bg: '#ffedd5', text: 'Partially Available', dot: '#ea580c' }
    return { color: '#059669', bg: '#d1fae5', text: 'Available', dot: '#059669' } // AVAILABLE
  }

  function formatDisplayRole(role) {
    if (!role) return '—';
    return role.replace(/_/g, ' ').replace(/\w\S*/g, (txt) => txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase());
  }

  function getRoleBadge(role) {
    if (!role) return { bg: '#e0e7ff', color: '#4f46e5' }; // default
    const r = role.toUpperCase();
    if (r === 'ADMIN') return { bg: '#ede9fe', color: '#7c3aed' };
    if (r.includes('PROJECT')) return { bg: '#e0f2fe', color: '#0284c7' };
    if (r.includes('LEAD') || r.includes('MANAGER')) return { bg: '#ffedd5', color: '#ea580c' };
    if (r.includes('DEVELOPER') || r.includes('FRONTEND') || r.includes('BACKEND')) return { bg: '#ede9fe', color: '#7c3aed' }; // Developer in mockup is purple
    if (r.includes('DESIGNER')) return { bg: '#dbeafe', color: '#2563eb' }; // UI/UX Designer is blue
    if (r.includes('TESTER') || r.includes('QA')) return { bg: '#d1fae5', color: '#059669' }; // Tester is green
    if (r.includes('ANALYST')) return { bg: '#fef3c7', color: '#d97706' }; // Business Analyst is yellow/orange
    if (r.includes('DEVOPS')) return { bg: '#fae8ff', color: '#c026d3' }; // DevOps is pink
    if (r.includes('HR')) return { bg: '#f3f4f6', color: '#4b5563' };
    return { bg: '#e0e7ff', color: '#4f46e5' }; // generic fallback
  }

  return (
    <div>
      <div className="page-header" style={{ marginBottom: 24, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <h1 className="page-heading">Resource Management</h1>
          <p className="page-subheading">View and allocate resources for your projects.</p>
        </div>
        <button className="btn btn-primary" onClick={() => { setEdit(null); setForm(true) }}>
          <Plus size={16}/> Allocate Resource
        </button>
      </div>

      {/* Filters */}
      <div className="card" style={{ display: 'flex', gap: 16, alignItems: 'flex-end', marginBottom: 24, padding: '20px 24px', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Project</label>
          <select className="form-select" value={projectF} onChange={e => { setProjectF(e.target.value); setPage(1) }}>
            <option value="">All Projects</option>
            {projects.map(p => (
              <option key={p.projectId} value={p.projectId}>{p.projectName}</option>
            ))}
          </select>
        </div>

        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Role</label>
          <select className="form-select" value={roleF} onChange={e => { setRoleF(e.target.value); setPage(1) }}>
            <option value="">All Roles</option>
            <option value="EMPLOYEE">Employee</option>
            <option value="PROJECT_MANAGER">Project Manager</option>
            {/* Can also dynamically pull distinct designations if we want, but sticking to basics */}
            {Array.from(new Set(users.map(u => u.designation).filter(Boolean))).map(d => (
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>

        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Availability</label>
          <select className="form-select" value={availF} onChange={e => { setAvailF(e.target.value); setPage(1) }}>
            <option value="">All</option>
            <option value="AVAILABLE">Available</option>
            <option value="PARTIALLY_AVAILABLE">Partially Available</option>
            <option value="UNAVAILABLE">Unavailable</option>
          </select>
        </div>

        <div style={{ flex: 1, minWidth: 200 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Search</label>
          <div style={{ position: 'relative' }}>
            <input
              type="text"
              className="form-input"
              placeholder="Search by name or skills..."
              value={searchInput}
              onChange={e => setSearchInput(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter') {
                  setSearch(searchInput)
                  setPage(1)
                }
              }}
              style={{ paddingRight: 32 }}
            />
            <button
              onClick={() => { setSearch(searchInput); setPage(1); }}
              title="Search"
              style={{
                position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)',
                background: 'transparent', border: 'none', cursor: 'pointer', padding: 0, display: 'flex', alignItems: 'center'
              }}
            >
              <Search size={16} color="var(--text-muted)" />
            </button>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        {isLoading ? <div className="page-loader"><div className="spinner"/></div> : (
          <>
            <div className="table-wrap" style={{ overflow: 'visible' }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Resource</th>
                    <th>Role</th>
                    <th>Skills</th>
                    <th>Project</th>
                    <th>Availability</th>
                    <th>Utilization</th>
                    <th style={{ textAlign: 'center' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paged.length === 0
                    ? <tr><td colSpan={7} className="table-empty">No resources found</td></tr>
                    : paged.map(u => {
                        const name = u.fullName || `${u.firstName || ''} ${u.lastName || ''}`.trim()
                        const { pct, projectNames, avail } = getUserAllocation(u.userId)
                        const badge  = availBadge(avail)
                        const skills = getSkillsForUser(u).join(', ')
                        const displayRole = u.designation || u.role?.replace('_', ' ') || ''
                        const rBadge = getRoleBadge(displayRole)
                        const avColor = getAvatarColor(name)

                        return (
                          <tr key={u.userId}>
                            <td>
                              <div className="user-cell">
                                <div className="avatar avatar-md" style={{ background: avColor.bg, color: avColor.color }}>{initials(name)}</div>
                                <div>
                                  <div className="user-name" style={{ fontSize: '0.85rem', fontWeight: 600 }}>{name}</div>
                                  <div className="user-email" style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>{u.email}</div>
                                </div>
                              </div>
                            </td>
                            <td>
                              <span style={{ background: rBadge.bg, color: rBadge.color, padding: '4px 10px', borderRadius: 6, fontSize: '0.75rem', fontWeight: 600 }}>
                                {formatDisplayRole(displayRole)}
                              </span>
                            </td>
                            <td style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', maxWidth: 220 }}>
                              {skills || '—'}
                            </td>
                            <td style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', maxWidth: 200 }}>
                              {projectNames || '—'}
                            </td>
                            <td>
                              <div style={{ display: 'flex', alignItems: 'center', gap: 6, background: badge.bg, color: badge.color, padding: '4px 10px', borderRadius: 6, width: 'fit-content', fontSize: '0.75rem', fontWeight: 600 }}>
                                <div style={{ width: 6, height: 6, borderRadius: '50%', background: badge.dot }} />
                                {badge.text}
                              </div>
                            </td>
                            <td>
                              <div style={{ display: 'flex', flexDirection: 'column', gap: 6, minWidth: 100 }}>
                                <span style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--text-main)' }}>{pct}%</span>
                                <div className="progress-bar" style={{ height: 6, width: '100%', background: 'var(--border)' }}>
                                  <div className={`progress-fill`} style={{ width: `${pct}%`, height: '100%', borderRadius: 10, background: 'var(--purple)' }}/>
                                </div>
                              </div>
                            </td>
                            <td>
                              <div style={{ position: 'relative', display: 'flex', justifyContent: 'center' }}>
                                <button
                                  style={{ background: 'transparent', border: 'none', cursor: 'pointer', padding: 4, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setOpenMenuId(openMenuId === u.userId ? null : u.userId);
                                  }}
                                >
                                  <MoreVertical size={18} color="var(--purple)" />
                                </button>
                                {openMenuId === u.userId && (
                                  <div style={{ position: 'absolute', right: 0, top: 24, background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 8, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', zIndex: 10, width: 150, overflow: 'hidden', textAlign: 'left' }} onClick={(e) => e.stopPropagation()}>
                                    <div style={{ padding: '10px 16px', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 500, color: 'var(--text-main)', borderBottom: '1px solid var(--border)' }} onClick={() => setOpenMenuId(null)}>View Details</div>
                                    <div style={{ padding: '10px 16px', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 500, color: 'var(--text-main)', borderBottom: 'none' }} onClick={() => { setOpenMenuId(null); setEdit(u); setForm(true); }}>Edit Allocation</div>
                                  </div>
                                )}
                              </div>
                            </td>
                          </tr>
                        )
                    })
                  }
                </tbody>
              </table>
            </div>

            <div className="pagination" style={{ borderTop: '1px solid var(--border)' }}>
              <span>Showing {total === 0 ? 0 : Math.min((page-1)*pageSize+1, total)} to {Math.min(page*pageSize, total)} of {total} resources</span>
              <div className="pag-controls">
                <button className="pag-btn" disabled={page === 1} onClick={() => setPage(p => p-1)}>‹</button>
                {Array.from({ length: Math.min(pages, 5) }, (_, i) => i+1).map(n => (
                  <button key={n} className={`pag-btn${page === n ? ' active' : ''}`} onClick={() => setPage(n)}>{n}</button>
                ))}
                <button className="pag-btn" disabled={page >= pages} onClick={() => setPage(p => p+1)}>›</button>
              </div>
            </div>
          </>
        )}
      </div>

      {showForm && (
        <AllocateModal
          resource={editing}
          users={users}
          projects={projects}
          onClose={() => { setForm(false); setEdit(null) }}
          onSaved={() => { qc.invalidateQueries({ queryKey: ['resources-list'] }); setForm(false); setEdit(null) }}
        />
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { resourceApi } from '../../../api/resourceApi'
import { userApi }     from '../../../api/userApi'
import { projectApi }  from '../../../api/projectApi'
import { Plus, Search, Eye, Pencil, MoreVertical } from 'lucide-react'
import { initials } from '../../../utils/formatDate'
import AllocateModal from '../components/AllocationForm'

// Map common roles → skill tags
const ROLE_SKILLS = {
  'PROJECT_MANAGER': ['Management', 'Planning', 'Leadership'],
  'ADMIN':           ['Administration', 'Management', 'Config'],
  'EMPLOYEE':        ['Development', 'Teamwork'],
  'FRONTEND':        ['React', 'JavaScript', 'UI/UX'],
  'BACKEND':         ['Java', 'Spring Boot', 'API'],
  'QA':              ['Testing', 'Selenium', 'Jira'],
  'DESIGNER':        ['Figma', 'UI Design', 'UX Research'],
  'DEVOPS':          ['AWS', 'Docker', 'CI/CD'],
  'ANALYST':         ['Analysis', 'Documentation', 'SQL'],
}

function getSkillsForUser(u) {
  const byRole = ROLE_SKILLS[u.role] || ROLE_SKILLS['EMPLOYEE']
  if (u.designation) {
    const d = u.designation.toUpperCase()
    if (d.includes('FRONTEND')) return ROLE_SKILLS['FRONTEND']
    if (d.includes('BACKEND'))  return ROLE_SKILLS['BACKEND']
    if (d.includes('QA'))       return ROLE_SKILLS['QA']
    if (d.includes('DESIGN'))   return ROLE_SKILLS['DESIGNER']
    if (d.includes('DEVOPS'))   return ROLE_SKILLS['DEVOPS']
    if (d.includes('ANALYST'))  return ROLE_SKILLS['ANALYST']
  }
  return byRole
}

function getAvatarColor(name) {
  const colors = [
    { bg: '#ede9fe', color: '#7c3aed' }, // purple
    { bg: '#d1fae5', color: '#059669' }, // green
    { bg: '#ffedd5', color: '#ea580c' }, // orange
    { bg: '#dbeafe', color: '#2563eb' }, // blue
    { bg: '#fae8ff', color: '#c026d3' }, // pink
  ];
  if (!name) return colors[0];
  const charCode = name.charCodeAt(0);
  return colors[charCode % colors.length];
}

export default function ResourceAllocationPage() {
  const qc = useQueryClient()

  // ── Filters
  const [search, setSearch] = useState('')
  const [searchInput, setSearchInput] = useState('')
  const [projectF, setProjectF] = useState('')
  const [roleF,  setRoleF]  = useState('')
  const [availF, setAvailF] = useState('')

  // ── Modals / Menus
  const [showForm, setForm] = useState(false)
  const [editing, setEdit]  = useState(null)
  const [openMenuId, setOpenMenuId] = useState(null)

  useEffect(() => {
    const handleClickOutside = () => setOpenMenuId(null);
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const [page, setPage]     = useState(1)
  const pageSize = 12

  const { data: resources = [] } = useQuery({
    queryKey: ['resources-list'],
    queryFn:  () => resourceApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 30_000,
  })

  const { data: users = [], isLoading } = useQuery({
    queryKey: ['users-list'],
    queryFn:  () => userApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 60_000,
  })

  const { data: projects = [] } = useQuery({
    queryKey: ['projects-list'],
    queryFn:  () => projectApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 60_000,
  })

  // Get allocation info for a user
  function getUserAllocation(userId) {
    const r = resources.filter(x => x.userId === userId)
    if (!r.length) return { pct: 0, projectNames: '', avail: 'AVAILABLE' }
    const pct = Math.min(r.reduce((s, x) => s + (x.allocationPercentage || 0), 0), 100)
    const projectNames = r.map(x => x.projectName || '').filter(Boolean).join(', ')
    const avail = pct >= 100 ? 'UNAVAILABLE' : pct > 0 ? 'PARTIALLY_AVAILABLE' : 'AVAILABLE'
    return { pct, projectNames, avail, projectIds: r.map(x => x.projectId).filter(Boolean) }
  }

  const filtered = users.filter(u => {
    const name = u.fullName || `${u.firstName || ''} ${u.lastName || ''}`

    // Search Match
    let matchS = true
    if (search) {
      const s = search.toLowerCase()
      const skillsText = getSkillsForUser(u).join(' ').toLowerCase()
      matchS = name.toLowerCase().includes(s) || u.email?.toLowerCase().includes(s) || skillsText.includes(s)
    }

    // Role Match
    const matchR = !roleF || u.role === roleF || u.designation === roleF

    const { avail, projectIds, projectNames } = getUserAllocation(u.userId)

    // Avail Match
    const matchA = !availF || avail === availF

    // Project Match
    const matchP = !projectF || projectIds.includes(Number(projectF)) || projectNames.includes(projectF)

    return matchS && matchR && matchA && matchP
  })

  const total = filtered.length
  const pages = Math.max(1, Math.ceil(total / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)

  function availBadge(avail) {
    if (avail === 'UNAVAILABLE') return { color: '#dc2626', bg: '#fee2e2', text: 'Unavailable', dot: '#dc2626' }
    if (avail === 'PARTIALLY_AVAILABLE') return { color: '#ea580c', bg: '#ffedd5', text: 'Partially Available', dot: '#ea580c' }
    return { color: '#059669', bg: '#d1fae5', text: 'Available', dot: '#059669' } // AVAILABLE
  }

  function formatDisplayRole(role) {
    if (!role) return '—';
    return role.replace(/_/g, ' ').replace(/\w\S*/g, (txt) => txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase());
  }

  function getRoleBadge(role) {
    if (!role) return { bg: '#e0e7ff', color: '#4f46e5' }; // default
    const r = role.toUpperCase();
    if (r === 'ADMIN') return { bg: '#ede9fe', color: '#7c3aed' };
    if (r.includes('PROJECT')) return { bg: '#e0f2fe', color: '#0284c7' };
    if (r.includes('LEAD') || r.includes('MANAGER')) return { bg: '#ffedd5', color: '#ea580c' };
    if (r.includes('DEVELOPER') || r.includes('FRONTEND') || r.includes('BACKEND')) return { bg: '#ede9fe', color: '#7c3aed' }; // Developer in mockup is purple
    if (r.includes('DESIGNER')) return { bg: '#dbeafe', color: '#2563eb' }; // UI/UX Designer is blue
    if (r.includes('TESTER') || r.includes('QA')) return { bg: '#d1fae5', color: '#059669' }; // Tester is green
    if (r.includes('ANALYST')) return { bg: '#fef3c7', color: '#d97706' }; // Business Analyst is yellow/orange
    if (r.includes('DEVOPS')) return { bg: '#fae8ff', color: '#c026d3' }; // DevOps is pink
    if (r.includes('HR')) return { bg: '#f3f4f6', color: '#4b5563' };
    return { bg: '#e0e7ff', color: '#4f46e5' }; // generic fallback
  }

  return (
    <div>
      <div className="page-header" style={{ marginBottom: 24, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <h1 className="page-heading">Resource Management</h1>
          <p className="page-subheading">View and allocate resources for your projects.</p>
        </div>
        <button className="btn btn-primary" onClick={() => { setEdit(null); setForm(true) }}>
          <Plus size={16}/> Allocate Resource
        </button>
      </div>

      {/* Filters */}
      <div className="card" style={{ display: 'flex', gap: 16, alignItems: 'flex-end', marginBottom: 24, padding: '20px 24px', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Project</label>
          <select className="form-select" value={projectF} onChange={e => { setProjectF(e.target.value); setPage(1) }}>
            <option value="">All Projects</option>
            {projects.map(p => (
              <option key={p.projectId} value={p.projectId}>{p.projectName}</option>
            ))}
          </select>
        </div>

        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Role</label>
          <select className="form-select" value={roleF} onChange={e => { setRoleF(e.target.value); setPage(1) }}>
            <option value="">All Roles</option>
            <option value="EMPLOYEE">Employee</option>
            <option value="PROJECT_MANAGER">Project Manager</option>
            {/* Can also dynamically pull distinct designations if we want, but sticking to basics */}
            {Array.from(new Set(users.map(u => u.designation).filter(Boolean))).map(d => (
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>

        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Availability</label>
          <select className="form-select" value={availF} onChange={e => { setAvailF(e.target.value); setPage(1) }}>
            <option value="">All</option>
            <option value="AVAILABLE">Available</option>
            <option value="PARTIALLY_AVAILABLE">Partially Available</option>
            <option value="UNAVAILABLE">Unavailable</option>
          </select>
        </div>

        <div style={{ flex: 1, minWidth: 200 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Search</label>
          <div style={{ position: 'relative' }}>
            <input
              type="text"
              className="form-input"
              placeholder="Search by name or skills..."
              value={searchInput}
              onChange={e => setSearchInput(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter') {
                  setSearch(searchInput)
                  setPage(1)
                }
              }}
              style={{ paddingRight: 32 }}
            />
            <button
              onClick={() => { setSearch(searchInput); setPage(1); }}
              title="Search"
              style={{
                position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)',
                background: 'transparent', border: 'none', cursor: 'pointer', padding: 0, display: 'flex', alignItems: 'center'
              }}
            >
              <Search size={16} color="var(--text-muted)" />
            </button>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        {isLoading ? <div className="page-loader"><div className="spinner"/></div> : (
          <>
            <div className="table-wrap" style={{ overflow: 'visible' }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Resource</th>
                    <th>Role</th>
                    <th>Skills</th>
                    <th>Project</th>
                    <th>Availability</th>
                    <th>Utilization</th>
                    <th style={{ textAlign: 'center' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paged.length === 0
                    ? <tr><td colSpan={7} className="table-empty">No resources found</td></tr>
                    : paged.map(u => {
                        const name = u.fullName || `${u.firstName || ''} ${u.lastName || ''}`.trim()
                        const { pct, projectNames, avail } = getUserAllocation(u.userId)
                        const badge  = availBadge(avail)
                        const skills = getSkillsForUser(u).join(', ')
                        const displayRole = u.designation || u.role?.replace('_', ' ') || ''
                        const rBadge = getRoleBadge(displayRole)
                        const avColor = getAvatarColor(name)

                        return (
                          <tr key={u.userId}>
                            <td>
                              <div className="user-cell">
                                <div className="avatar avatar-md" style={{ background: avColor.bg, color: avColor.color }}>{initials(name)}</div>
                                <div>
                                  <div className="user-name" style={{ fontSize: '0.85rem', fontWeight: 600 }}>{name}</div>
                                  <div className="user-email" style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>{u.email}</div>
                                </div>
                              </div>
                            </td>
                            <td>
                              <span style={{ background: rBadge.bg, color: rBadge.color, padding: '4px 10px', borderRadius: 6, fontSize: '0.75rem', fontWeight: 600 }}>
                                {formatDisplayRole(displayRole)}
                              </span>
                            </td>
                            <td style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', maxWidth: 220 }}>
                              {skills || '—'}
                            </td>
                            <td style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', maxWidth: 200 }}>
                              {projectNames || '—'}
                            </td>
                            <td>
                              <div style={{ display: 'flex', alignItems: 'center', gap: 6, background: badge.bg, color: badge.color, padding: '4px 10px', borderRadius: 6, width: 'fit-content', fontSize: '0.75rem', fontWeight: 600 }}>
                                <div style={{ width: 6, height: 6, borderRadius: '50%', background: badge.dot }} />
                                {badge.text}
                              </div>
                            </td>
                            <td>
                              <div style={{ display: 'flex', flexDirection: 'column', gap: 6, minWidth: 100 }}>
                                <span style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--text-main)' }}>{pct}%</span>
                                <div className="progress-bar" style={{ height: 6, width: '100%', background: 'var(--border)' }}>
                                  <div className={`progress-fill`} style={{ width: `${pct}%`, height: '100%', borderRadius: 10, background: 'var(--purple)' }}/>
                                </div>
                              </div>
                            </td>
                            <td>
                              <div style={{ position: 'relative', display: 'flex', justifyContent: 'center' }}>
                                <button
                                  style={{ background: 'transparent', border: 'none', cursor: 'pointer', padding: 4, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setOpenMenuId(openMenuId === u.userId ? null : u.userId);
                                  }}
                                >
                                  <MoreVertical size={18} color="var(--purple)" />
                                </button>
                                {openMenuId === u.userId && (
                                  <div style={{ position: 'absolute', right: 0, top: 24, background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 8, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', zIndex: 10, width: 150, overflow: 'hidden', textAlign: 'left' }} onClick={(e) => e.stopPropagation()}>
                                    <div style={{ padding: '10px 16px', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 500, color: 'var(--text-main)', borderBottom: '1px solid var(--border)' }} onClick={() => setOpenMenuId(null)}>View Details</div>
                                    <div style={{ padding: '10px 16px', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 500, color: 'var(--text-main)', borderBottom: 'none' }} onClick={() => { setOpenMenuId(null); setEdit(u); setForm(true); }}>Edit Allocation</div>
                                  </div>
                                )}
                              </div>
                            </td>
                          </tr>
                        )
                    })
                  }
                </tbody>
              </table>
            </div>

            <div className="pagination" style={{ borderTop: '1px solid var(--border)' }}>
              <span>Showing {total === 0 ? 0 : Math.min((page-1)*pageSize+1, total)} to {Math.min(page*pageSize, total)} of {total} resources</span>
              <div className="pag-controls">
                <button className="pag-btn" disabled={page === 1} onClick={() => setPage(p => p-1)}>‹</button>
                {Array.from({ length: Math.min(pages, 5) }, (_, i) => i+1).map(n => (
                  <button key={n} className={`pag-btn${page === n ? ' active' : ''}`} onClick={() => setPage(n)}>{n}</button>
                ))}
                <button className="pag-btn" disabled={page >= pages} onClick={() => setPage(p => p+1)}>›</button>
              </div>
            </div>
          </>
        )}
      </div>

      {showForm && (
        <AllocateModal
          resource={editing}
          users={users}
          projects={projects}
          onClose={() => { setForm(false); setEdit(null) }}
          onSaved={() => { qc.invalidateQueries({ queryKey: ['resources-list'] }); setForm(false); setEdit(null) }}
        />
      )}
    </div>
  )
}

