import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useAuthStore } from '../../../store/authStore'
import { userApi } from '../../../api/userApi'
import { projectApi } from '../../../api/projectApi'
import { useRole } from '../../../store/useRole'
import { Plus, Search, Users, UserCheck, UserX, UserMinus, MoreVertical, RefreshCcw, Folder } from 'lucide-react'
import { formatDate, initials } from '../../../utils/formatDate'
import UserFormModal from '../components/UserForm'

function getAvatarColor(name) {
  const sum = name.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0)
  const colors = [
    { bg: '#fee2e2', color: '#dc2626' },
    { bg: '#dbeafe', color: '#2563eb' },
    { bg: '#d1fae5', color: '#059669' },
    { bg: '#fef3c7', color: '#d97706' },
    { bg: '#e0e7ff', color: '#4f46e5' },
    { bg: '#fae8ff', color: '#c026d3' },
  ]
  return colors[sum % colors.length]
}

export default function UsersPage() {
  const qc = useQueryClient()
  const currentUserId = useAuthStore(s => s.user?.userId)
  const { isPM, isEmployee } = useRole()

  // ── Filters
  const [search, setSearch] = useState('')
  const [searchInput, setSearchInput] = useState('')
  const [roleF, setRoleF] = useState('')
  const [statusF, setStatusF] = useState('')
  const [deptF, setDeptF] = useState('')
  const [projectF, setProjectF] = useState('')

  // ── Modals / Menus
  const [showForm, setForm] = useState(false)
  const [editing, setEditing] = useState(null)
  const [openMenuId, setOpenMenuId] = useState(null)

  useEffect(() => {
    const handleClickOutside = () => setOpenMenuId(null);
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  const [page, setPage] = useState(1)
  const pageSize = 10

  const { data: raw = [], isLoading } = useQuery({
    queryKey: ['users-list'],
    queryFn: () => userApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 30_000,
  })

  const { data: projects = [] } = useQuery({
    queryKey: ['projects-list'],
    queryFn: () => projectApi.getAll().then(r => r.data?.data || r.data || []),
    staleTime: 60_000,
    enabled: isPM,
  })

  const deleteMut = useMutation({
    mutationFn: (id) => userApi.delete(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['users-list'] }),
  })

  // Ensure every user has a status, default to ACTIVE if missing
  const dataWithStatus = raw.map(u => ({ ...u, status: u.status || 'ACTIVE' }));

  const filtered = dataWithStatus.filter(u => {
    const name = u.fullName || `${u.firstName || ''} ${u.lastName || ''}`

    // Search match
    let matchSearch = true;
    if (search) {
      const s = search.toLowerCase()
      matchSearch = name.toLowerCase().includes(s) || u.email?.toLowerCase().includes(s)
    }

    const matchRole = !roleF || u.role === roleF || u.designation === roleF
    const matchStatus = !statusF || u.status === statusF
    const matchDept = !deptF || u.department === deptF
    return matchSearch && matchRole && matchStatus && matchDept
  })

  const total = filtered.length
  const pages = Math.max(1, Math.ceil(total / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)

  // Summary logic
  const totalUsersCount = filtered.length
  const activeCount = filtered.filter(u => u.status === 'ACTIVE').length
  const inactiveCount = filtered.filter(u => u.status === 'INACTIVE').length
  const blockedCount = filtered.filter(u => u.status === 'BLOCKED').length

  const pct = (n) => totalUsersCount ? Math.round((n / totalUsersCount) * 100) : 0

  function getRoleBadge(role, designation) {
    const r = (designation || role || '').toUpperCase();
    if (r === 'ADMIN') return { bg: '#ede9fe', color: '#7c3aed' };
    if (r.includes('PROJECT')) return { bg: '#e0f2fe', color: '#0284c7' };
    if (r.includes('LEAD') || r.includes('MANAGER')) return { bg: '#ffedd5', color: '#ea580c' };
    if (r.includes('DEVELOPER')) return { bg: '#dbeafe', color: '#2563eb' };
    if (r.includes('DESIGN') || r.includes('UI')) return { bg: '#f3e8ff', color: '#9333ea' };
    if (r.includes('TESTER') || r.includes('QA')) return { bg: '#fae8ff', color: '#c026d3' };
    if (r.includes('ANALYST')) return { bg: '#fef3c7', color: '#d97706' };
    if (r.includes('WRITER')) return { bg: '#e0f2fe', color: '#0284c7' };
    if (r.includes('HR')) return { bg: '#f3f4f6', color: '#4b5563' };
    return { bg: '#e0e7ff', color: '#4f46e5' };
  }

  function getStatusBadge(status) {
    const s = (status || '').toUpperCase();
    if (s === 'ACTIVE') return { bg: '#d1fae5', color: '#059669' };
    if (s === 'INACTIVE') return { bg: '#fee2e2', color: '#dc2626' };
    if (s === 'BLOCKED') return { bg: '#fee2e2', color: '#dc2626' };
    return { bg: '#f3f4f6', color: '#6b7280' };
  }

  function formatDisplayRole(role) {
    if (!role) return '—';
    return role.replace(/_/g, ' ').replace(/\w\S*/g, (txt) => txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase());
  }

  function handleDelete(id, name) {
    if (String(id) === String(currentUserId)) {
      alert('You cannot delete your own account.')
      return
    }
    if (window.confirm(`Delete user "${name}"? This action cannot be undone.`)) deleteMut.mutate(id)
  }

  const handleActionClick = (action, user) => {
    setOpenMenuId(null);
    if (action === 'edit') {
      setEditing(user);
      setForm(true);
    } else if (action === 'delete') {
      const name = user.fullName || `${user.firstName || ''} ${user.lastName || ''}`.trim()
      handleDelete(user.userId, name);
    }
  }

  return (
    <div>
      <div className="page-header" style={{ marginBottom: 24, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <div>
          <h1 className="page-heading">{isPM ? 'Team Members' : 'Users'}</h1>
          <p className="page-subheading">{isPM ? 'View and manage members of your project.' : 'Manage all users and their access in the system.'}</p>
        </div>
        <button className="btn btn-primary" onClick={() => { setEditing(null); setForm(true) }}>
          <Plus size={16} /> {isPM ? 'Add Member' : 'Add User'}
        </button>
      </div>

      {/* Summary Cards */}
      {isPM ? (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 24 }}>
          {/* Project Dropdown Card */}
          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#f3e8ff', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <Folder size={22} color="#9333ea" />
              </div>
              <div style={{ width: '100%' }}>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 4 }}>Project</div>
                <select 
                  className="form-select" 
                  style={{ width: '100%', padding: '4px 8px', fontSize: '1rem', fontWeight: 600, border: 'none', background: 'transparent', cursor: 'pointer', appearance: 'auto', outline: 'none' }}
                  value={projectF} 
                  onChange={e => { setProjectF(e.target.value); setPage(1) }}
                >
                  <option value="">All Projects</option>
                  {projects.map(p => (
                    <option key={p.projectId} value={p.projectId}>{p.projectName}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#ede9fe', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Users size={22} color="#7c3aed" />
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>Total Members</div>
                <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--text-main)', lineHeight: 1.2 }}>{totalUsersCount}</div>
              </div>
            </div>
            <div style={{ marginTop: 'auto', paddingTop: 16, fontSize: '0.8rem', fontWeight: 500, color: 'var(--text-secondary)' }}>
              View all members
            </div>
          </div>

          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#d1fae5', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <UserCheck size={22} color="#059669" />
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>Active Members</div>
                <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--text-main)', lineHeight: 1.2 }}>{activeCount}</div>
              </div>
            </div>
            <div style={{ marginTop: 'auto', paddingTop: 16, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: '0.8rem', fontWeight: 500, color: 'var(--text-secondary)' }}>{pct(activeCount)}% of total</span>
              <div style={{ width: 40, height: 4, borderRadius: 4, background: 'var(--border)' }}>
                <div style={{ width: `${pct(activeCount)}%`, height: 4, borderRadius: 4, background: '#059669' }} />
              </div>
            </div>
          </div>

          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#fee2e2', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <UserX size={22} color="#dc2626" />
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>Inactive Members</div>
                <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--text-main)', lineHeight: 1.2 }}>{inactiveCount}</div>
              </div>
            </div>
            <div style={{ marginTop: 'auto', paddingTop: 16, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: '0.8rem', fontWeight: 500, color: 'var(--text-secondary)' }}>{pct(inactiveCount)}% of total</span>
              <div style={{ width: 40, height: 4, borderRadius: 4, background: 'var(--border)' }}>
                <div style={{ width: `${pct(inactiveCount)}%`, height: 4, borderRadius: 4, background: '#dc2626' }} />
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 24 }}>
          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#ede9fe', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Users size={22} color="#7c3aed" />
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>Total Users</div>
                <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--text-main)', lineHeight: 1.2 }}>{totalUsersCount}</div>
              </div>
            </div>
            <div style={{ marginTop: 'auto', paddingTop: 16, fontSize: '0.8rem', fontWeight: 500, color: 'var(--text-secondary)' }}>
              View all users
            </div>
          </div>

          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#d1fae5', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <UserCheck size={22} color="#059669" />
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>Active Users</div>
                <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--text-main)', lineHeight: 1.2 }}>{activeCount}</div>
              </div>
            </div>
            <div style={{ marginTop: 'auto', paddingTop: 16, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: '0.8rem', fontWeight: 500, color: 'var(--text-secondary)' }}>{pct(activeCount)}% of total</span>
              <div style={{ width: 40, height: 4, borderRadius: 4, background: 'var(--border)' }}>
                <div style={{ width: `${pct(activeCount)}%`, height: 4, borderRadius: 4, background: '#059669' }} />
              </div>
            </div>
          </div>

          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#ffedd5', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <UserMinus size={22} color="#ea580c" />
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>Inactive Users</div>
                <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--text-main)', lineHeight: 1.2 }}>{inactiveCount}</div>
              </div>
            </div>
            <div style={{ marginTop: 'auto', paddingTop: 16, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: '0.8rem', fontWeight: 500, color: 'var(--text-secondary)' }}>{pct(inactiveCount)}% of total</span>
              <div style={{ width: 40, height: 4, borderRadius: 4, background: 'var(--border)' }}>
                <div style={{ width: `${pct(inactiveCount)}%`, height: 4, borderRadius: 4, background: '#ea580c' }} />
              </div>
            </div>
          </div>

          <div className="card" style={{ padding: '20px 24px', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ width: 44, height: 44, borderRadius: 10, background: '#fee2e2', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <UserX size={22} color="#dc2626" />
              </div>
              <div>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-secondary)' }}>Blocked Users</div>
                <div style={{ fontSize: '1.75rem', fontWeight: 700, color: 'var(--text-main)', lineHeight: 1.2 }}>{blockedCount}</div>
              </div>
            </div>
            <div style={{ marginTop: 'auto', paddingTop: 16, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{ fontSize: '0.8rem', fontWeight: 500, color: 'var(--text-secondary)' }}>{pct(blockedCount)}% of total</span>
              <div style={{ width: 40, height: 4, borderRadius: 4, background: 'var(--border)' }}>
                <div style={{ width: `${pct(blockedCount)}%`, height: 4, borderRadius: 4, background: '#dc2626' }} />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Filters Row */}
      <div className="card" style={{ display: 'flex', gap: 16, alignItems: 'flex-end', marginBottom: 24, padding: '20px 24px', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Role</label>
          <select className="form-select" value={roleF} onChange={e => { setRoleF(e.target.value); setPage(1) }}>
            <option value="">All Roles</option>
            {!isPM && <option value="ADMIN">Admin</option>}
            <option value="PROJECT_MANAGER">Project Manager</option>
            <option value="EMPLOYEE">Employee</option>
          </select>
        </div>

        <div style={{ flex: 1, minWidth: 160 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Status</label>
          <select className="form-select" value={statusF} onChange={e => { setStatusF(e.target.value); setPage(1) }}>
            <option value="">All Status</option>
            <option value="ACTIVE">Active</option>
            <option value="INACTIVE">Inactive</option>
            {!isPM && <option value="BLOCKED">Blocked</option>}
          </select>
        </div>

        {!isPM && (
          <div style={{ flex: 1, minWidth: 160 }}>
            <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Department</label>
            <select className="form-select" value={deptF} onChange={e => { setDeptF(e.target.value); setPage(1) }}>
              <option value="">All Departments</option>
              {Array.from(new Set(dataWithStatus.map(u => u.department).filter(Boolean))).map(d => (
                <option key={d} value={d}>{d}</option>
              ))}
            </select>
          </div>
        )}

        <div style={{ flex: 1, minWidth: 200 }}>
          <label style={{ fontSize: '0.85rem', fontWeight: 600, display: 'block', marginBottom: 8, color: 'var(--text-primary)' }}>Search</label>
          <div style={{ position: 'relative' }}>
            <input
              type="text"
              className="form-input"
              placeholder="Search by name or email..."
              value={searchInput}
              onChange={e => setSearchInput(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter') {
                  setSearch(searchInput)
                  setPage(1)
                }
              }}
              style={{ paddingRight: 32 }}
            />
            <button
              onClick={() => { setSearch(searchInput); setPage(1); }}
              title="Search"
              style={{
                position: 'absolute', right: 10, top: '50%', transform: 'translateY(-50%)',
                background: 'transparent', border: 'none', cursor: 'pointer', padding: 0, display: 'flex', alignItems: 'center'
              }}
            >
              <Search size={16} color="var(--text-muted)" />
            </button>
          </div>
        </div>

        <div>
          <button 
            className="btn btn-ghost btn-sm" 
            onClick={() => { setSearch(''); setSearchInput(''); setRoleF(''); setStatusF(''); setDeptF(''); setProjectF(''); setPage(1); }} 
            style={{ 
              background: 'transparent', border: '1px solid var(--purple-light)', color: 'var(--purple)', 
              height: 38, padding: '0 16px', borderRadius: 'var(--radius-sm)', display: 'flex', alignItems: 'center', 
              gap: 8, fontWeight: 500, fontSize: '0.85rem', cursor: 'pointer' 
            }}
          >
            <RefreshCcw size={14} /> Clear Filter
          </button>
        </div>
      </div>

      {/* Data Table */}
      <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
        {isLoading ? <div className="page-loader"><div className="spinner" /></div> : (
          <>
            <div className="table-wrap" style={{ overflow: 'visible' }}>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Member</th>
                    <th>Role</th>
                    <th>Department</th>
                    <th>Status</th>
                    <th>Joined On</th>
                    <th style={{ textAlign: 'center' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paged.length === 0
                    ? <tr><td colSpan={6} className="table-empty">No members found</td></tr>
                    : paged.map(u => {
                      const name = u.fullName || `${u.firstName || ''} ${u.lastName || ''}`.trim()
                      const displayRole = u.designation || u.role
                      const rBadge = getRoleBadge(u.role, u.designation);
                      const sBadge = getStatusBadge(u.status);
                      const avColor = getAvatarColor(name);

                      return (
                        <tr key={u.userId}>
                          <td>
                            <div className="user-cell">
                              <div className="avatar avatar-md" style={{ background: avColor.bg, color: avColor.color }}>{initials(name)}</div>
                              <div>
                                <div className="user-name" style={{ fontSize: '0.85rem', fontWeight: 600 }}>{name}</div>
                                <div className="user-email" style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>{u.email}</div>
                              </div>
                            </div>
                          </td>
                          <td>
                            <span style={{ background: rBadge.bg, color: rBadge.color, padding: '4px 10px', borderRadius: 6, fontSize: '0.75rem', fontWeight: 600 }}>
                              {formatDisplayRole(displayRole)}
                            </span>
                          </td>
                          <td style={{ fontSize: '0.85rem', color: 'var(--text-main)', fontWeight: 500 }}>{u.department || '—'}</td>
                          <td>
                            <span style={{ background: sBadge.bg, color: sBadge.color, padding: '4px 10px', borderRadius: 6, fontSize: '0.75rem', fontWeight: 600 }}>
                              {formatDisplayRole(u.status)}
                            </span>
                          </td>
                          <td style={{ fontSize: '0.85rem', color: 'var(--text-main)', fontWeight: 500 }}>{formatDate(u.createdAt)}</td>
                          <td>
                            <div style={{ position: 'relative', display: 'flex', justifyContent: 'center' }}>
                              <button
                                style={{ background: 'transparent', border: 'none', cursor: 'pointer', padding: 4, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setOpenMenuId(openMenuId === u.userId ? null : u.userId);
                                }}
                              >
                                <MoreVertical size={18} color="var(--purple)" />
                              </button>
                              {openMenuId === u.userId && (
                                <div style={{ position: 'absolute', right: 0, top: 24, background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 8, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', zIndex: 10, width: 140, overflow: 'hidden', textAlign: 'left' }} onClick={(e) => e.stopPropagation()}>
                                  <div style={{ padding: '10px 16px', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 500, color: 'var(--text-main)', borderBottom: '1px solid var(--border)' }} onClick={() => setOpenMenuId(null)}>View Details</div>
                                  <div style={{ padding: '10px 16px', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 500, color: 'var(--text-main)', borderBottom: isPM ? 'none' : '1px solid var(--border)' }} onClick={() => handleActionClick('edit', u)}>Edit Member</div>
                                  {!isPM && <div style={{ padding: '10px 16px', fontSize: '0.85rem', cursor: 'pointer', fontWeight: 500, color: '#dc2626' }} onClick={() => handleActionClick('delete', u)}>Delete Member</div>}
                                </div>
                              )}
                            </div>
                          </td>
                        </tr>
                      )
                    })
                  }
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div className="pagination" style={{ borderTop: '1px solid var(--border)' }}>
              <span>Showing {total === 0 ? 0 : Math.min((page - 1) * pageSize + 1, total)} to {Math.min(page * pageSize, total)} of {total} members</span>
              <div className="pag-controls">
                <button className="pag-btn" disabled={page === 1} onClick={() => setPage(p => p - 1)}>‹</button>
                {Array.from({ length: Math.min(pages, 5) }, (_, i) => i + 1).map(n => (
                  <button key={n} className={`pag-btn${page === n ? ' active' : ''}`} onClick={() => setPage(n)}>{n}</button>
                ))}
                <button className="pag-btn" disabled={page >= pages} onClick={() => setPage(p => p + 1)}>›</button>
              </div>
            </div>
          </>
        )}
      </div>

      {/* User Edit Modal */}
      {showForm && (
        <UserFormModal
          user={editing}
          onClose={() => { setForm(false); setEditing(null) }}
          onSaved={() => { qc.invalidateQueries({ queryKey: ['users-list'] }); setForm(false); setEditing(null) }}
        />
      )}
    </div>
  )
}
